// Holiday greeting slides ("holiday mode").
// When enabled, a "happy holiday" slide is added to the playlist around each festive holiday.
// Each holiday has its own campaign artwork (public/shared/greetings/<key>.svg, with its own typeface and the Eitan Medical logo drawn in), shown full screen. The SVGs are generated by
// scripts/greetings/campaign.py. Solemn days (Holocaust Day, Memorial Day, Tisha B'Av) never get a greeting.

export const GREETINGS = {
  rosh_hashana: { he: 'שנה טובה ומתוקה', en: 'Shana Tova', color: '#b8322a' },
  yom_kippur: { he: 'גמר חתימה טובה', en: "G'mar Chatima Tova", color: '#1d2b4f' },
  sukkot: { he: 'חג סוכות שמח', en: 'Happy Sukkot', color: '#3d7a2f' },
  simchat_torah: { he: 'שמחת תורה שמחה', en: 'Happy Simchat Torah', color: '#1f4fa8' },
  hanukkah: { he: 'חנוכה שמח', en: 'Happy Hanukkah', color: '#0b2a6b' },
  tu_bishvat: { he: 'ט״ו בשבט שמח', en: 'Happy Tu BiShvat', color: '#4c8c2b' },
  purim: { he: 'פורים שמח', en: 'Happy Purim', color: '#a3168f' },
  pesach: { he: 'חג פסח כשר ושמח', en: 'Happy Passover', color: '#1b7f86' },
  yom_haatzmaut: { he: 'יום עצמאות שמח', en: 'Happy Independence Day', color: '#0038b8' },
  lag_baomer: { he: 'ל״ג בעומר שמח', en: 'Happy Lag BaOmer', color: '#c2470e' },
  yom_yerushalayim: { he: 'יום ירושלים שמח', en: 'Happy Jerusalem Day', color: '#a8741f' },
  shavuot: { he: 'חג שבועות שמח', en: 'Happy Shavuot', color: '#6d9a2c' },
};
export const GREETING_KEYS = Object.keys(GREETINGS);

const addDays = (dateStr, n) => {
  const [y, m, d] = dateStr.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d) + n * 86400e3).toISOString().slice(0, 10);
};

/** Which holiday greeting is due on local date `dateStr`, or null. */
export function activeGreeting(holidays = {}, dateStr, daysBefore = 3) {
  const before = Math.max(0, Math.min(14, Number(daysBefore) || 0));
  for (const key of GREETING_KEYS) {
    for (const o of holidays[key] || []) {
      if (dateStr >= addDays(o.start, -before) && dateStr <= addDays(o.start, (o.days || 1) - 1)) return key;
    }
  }
  return null;
}

export const greetingArtUrl = (key) => `/shared/greetings/${key}.svg`;

/**
 * Build the greeting slide for `key`. opts: { duration }.
 * The whole slide is one illustration: headline type and the Eitan Medical logo are drawn into the artwork
 * (each holiday has its own typeface, embedded in the SVG), so there are no overlay elements.
 */
export function greetingSlide(key, { duration = 12 } = {}) {
  if (!GREETINGS[key]) return null;
  return {
    id: `holiday-${key}`, categoryId: null, sort: 1e9, name: GREETINGS[key].he, enabled: true, duration: Math.max(5, Number(duration) || 12),
    transition: { type: 'fade', duration: 1400 },
    background: { type: 'image', assetId: 'holiday-art', fit: 'cover', color: GREETINGS[key].color },
    elements: [],
    _assets: { 'holiday-art': { id: 'holiday-art', url: greetingArtUrl(key), mime: 'image/svg+xml' } },
    _greeting: key,
  };
}
